package com.jarvis.client.localai

/**
 * Every word the Local AI screen says, in one pure Kotlin file.
 *
 * The same reason `MoreMenuWords` and `ScreenRate` exist: a JVM test can hold
 * the promises still, and a source-pin test can name the one permanent label
 * once instead of retyping it. None of this text is generated by a model.
 *
 * Three rules are visible in the wording:
 * - the permanent label says the model runs on this phone, not the PC;
 * - nothing is ever described as downloaded, because nothing here downloads;
 * - speed is "not measured" until the native side reports real token counts.
 */
object LocalAiWords {

    /** The screen's title, and the More menu row's label. */
    const val TITLE = "Local AI"

    /**
     * The permanent label. The task brief fixes this sentence word for word,
     * so `LocalAiShipsOffTest` pins it and the screen draws it while the
     * switch is on AND while it is off.
     */
    const val PERMANENT_LABEL = "On-device model: runs on this phone, not your PC"

    /** The line under the title. */
    const val SUBTITLE = "A small model on this phone, with no PC and no internet"

    /** The More menu row's own line, so the menu explains where it goes. */
    const val MORE_DETAIL = "Runs a model on this phone, not your PC"

    /** What the screen is, before the switch. */
    const val INTRO =
        "Jarvis can run a small model on this phone by itself, with no PC and no internet. " +
            "It is a separate chat: it never replaces the Jarvis chat that uses your PC, and " +
            "nothing on this screen is sent anywhere."

    /** Off is the shipped state, said plainly. */
    const val OFF_NOTE =
        "Off until you turn it on. Nothing downloads by itself, and no model is loaded until " +
            "you pick one and tap Load."

    /** The switch's label. */
    const val SWITCH_LABEL = "Use a model on this phone"

    /** Beside the switch when on. */
    const val SWITCH_ON_DETAIL = "On. Models stay on this phone."

    /** Beside the switch when off. */
    const val SWITCH_OFF_DETAIL = "Off. The ordinary Jarvis chat that uses your PC is unchanged."

    /** Where a model comes from. */
    const val BRING_YOUR_OWN =
        "The model is a .gguf file you bring yourself - copy it to this phone over USB, or " +
            "download it on another device and copy it across. Jarvis never downloads a model."

    /** The import button. */
    const val IMPORT = "Import a model"

    /**
     * Exactly what to tap, because a file picker is the one step where a
     * beginner can get lost: name the button, name the picker, name the
     * confirming tap.
     */
    const val IMPORT_HELP =
        "Tap Import a model, choose the .gguf file in the file picker, then tap Open. " +
            "Jarvis copies it into its own folder on this phone."

    /** The import button's label while a copy is running. */
    const val IMPORTING = "Copying…"

    /** An empty list, with the next action in it. */
    const val NO_MODELS =
        "No models on this phone yet. Copy a .gguf model file here, then tap Import a model."

    /** The model list's heading. */
    const val MODELS = "Models on this phone"

    /** The Load action. */
    const val LOAD = "Load"

    /** The Unload action. */
    const val UNLOAD = "Unload"

    /** Shown while a model is loading. */
    const val LOADING = "Loading…"

    /** The Delete action. */
    const val DELETE = "Delete"

    /** The confirmation before a model file is removed. */
    fun deleteQuestion(name: String): String =
        "Delete $name from this phone? The file is removed from this phone only. " +
            "You can import it again."

    const val DELETE_YES = "Delete it"

    const val CANCEL = "Cancel"

    /** The chat's heading, shown only once a model is loaded. */
    const val CHAT = "Ask the model on this phone"

    /** The chat box's placeholder. */
    const val ASK_PLACEHOLDER = "Ask something small"

    /** The chat's first line, before anything is asked. */
    const val CHAT_EMPTY = "Nothing asked yet. Type below, then tap Send."

    /** Shown where the answer will appear, while the phone works on it. */
    const val THINKING = "Thinking…"

    /** The send action. */
    const val SEND = "Send"

    /**
     * Discards the draft. The draft is `rememberSaveable`, so it survives
     * leaving the screen; before this there was no way to throw a stale or
     * half-typed question away except killing the app (field test, 2026-11-13).
     */
    const val CLEAR = "Clear"

    /** Where the chat lives. */
    const val CHAT_NOTE =
        "This chat stays on this phone. It is not saved, and it is not the chat that uses your PC."

    /** The per-reply speed line when the native side reported no numbers. */
    const val NOT_MEASURED = "Speed: not measured"

    /** The per-reply speed line when it did. */
    fun speedLine(tokensPerSecond: Double?): String =
        if (tokensPerSecond == null || !tokensPerSecond.isFinite() || tokensPerSecond <= 0.0) {
            NOT_MEASURED
        } else {
            String.format(java.util.Locale.UK, "Measured: %.1f tokens per second", tokensPerSecond)
        }

    /** What the owner must do first, when they press something too early. */
    const val TURN_ON_FIRST = "Turn the switch on first, then import or load a model."

    /** What the owner must do when there is no loaded model. */
    const val LOAD_FIRST = "Load a model first, then ask it something."

    /** Said after the 180-second cap stopped a reply. */
    const val HARD_CAP_NOTE =
        "Stopped: one reply is limited to 3 minutes, so the phone stays usable. " +
            "What arrived is shown."

    /** The short line under the reply itself, when the cap ended it. */
    const val HARD_CAP_SHORT = "Stopped at the 3-minute limit for one reply."

    /**
     * Said after the five-minute idle rule frees the model. The window was
     * 5 seconds until the 2026-11-13 field test measured it unloading the
     * model before a person could start typing; five minutes is the session
     * window now.
     */
    const val IDLE_UNLOAD_NOTE =
        "Jarvis unloaded the model after 5 minutes with nothing asked, to give the phone its " +
            "memory back."

    /** Said when the native library is not in this build. */
    const val NO_ENGINE_NOTE =
        "This build of Jarvis does not have the on-device engine yet. The screen is ready; " +
            "the engine arrives with a later build."

    /** A line under the model's size and quant. */
    fun modelDetail(model: LocalAiModel): String {
        val size = DeviceTiers.bytesText(model.bytes)
        val quant = model.quant ?: return size
        val fromName = if (model.quantFromName) " (from the file name)" else ""
        return "$quant · $size$fromName"
    }

    /** A copy's progress line. */
    fun progressLine(copied: Long, total: Long?): String {
        if (total == null || total <= 0L) {
            return "Copying: ${DeviceTiers.bytesText(copied)}"
        }
        val percent = ((copied * 100L) / total).coerceIn(0L, 100L)
        return "Copying: $percent% of ${DeviceTiers.bytesText(total)}"
    }

    /** The one-sentence confirmation after an import. */
    fun imported(name: String): String = "$name is on this phone now. Tap Load to use it."

    /** The line under a too-big model's verdict, in the screen's own voice. */
    const val TOO_BIG_ACTION =
        "Jarvis will not load this one, so the phone cannot be pushed into closing the app."

    /** Shown while the model list is being read. */
    const val READING = "Reading the models on this phone…"
}
